do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_scoring_criteria t where id='23a9229f-ece2-5f47-ac56-c0d1b620403e'; if prior is not null then if not prior @> '{"id":"23a9229f-ece2-5f47-ac56-c0d1b620403e","leaf_id":"144f5cd5-dca6-5b40-9b91-a4c2311d78df","source_id":"2dd2f647-f6b6-5753-a3cc-490349c08cd1","criterion_key":"q2-7","description":"공식 세부 평가표(100점 척도, 문항 배점 50점) · 확률변수의 기댓값(10)","official_points":null,"rubric_dimensions":["logical_development","computation_accuracy","final_conclusion"]}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_scoring_criteria (id,leaf_id,source_id,criterion_key,description,official_points,rubric_dimensions) values ('23a9229f-ece2-5f47-ac56-c0d1b620403e','144f5cd5-dca6-5b40-9b91-a4c2311d78df','2dd2f647-f6b6-5753-a3cc-490349c08cd1','q2-7','공식 세부 평가표(100점 척도, 문항 배점 50점) · 확률변수의 기댓값(10)',NULL,ARRAY['logical_development','computation_accuracy','final_conclusion']::text[]); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='c40a215a-ebb1-56e2-bade-5d2beec360e3'; if prior is not null then if not prior @> '{"id":"c40a215a-ebb1-56e2-bade-5d2beec360e3","leaf_id":"144f5cd5-dca6-5b40-9b91-a4c2311d78df","source_id":"e84e5e0e-677c-5ff3-9044-708d4ee08d8a","origin":"OFFICIAL","body":"현의 중점 M은 OM=1/2이다. 사면체의 높이와 밑넓이를 비교하면 최대일 때 H는 AB의 수직이등분선 위에서 O를 기준으로 M 반대편에 있다. t=OH라 하면 부피는 √3(2t+1)√(1−t²)/12. 도함수 부호가 바뀌는 t=(√33−1)/8에서 밑넓이는 √3(1/2+t)/2=3(√3+√11)/16이다.\n원점은 항상 교점이다. 0<m<1에서는 0<x≤1에서 g(x)≤x<f(x). m=1에서는 (1,1)도 교점이다. 1<m<2에서는 양의 교점 방정식이 h(x)=x^(2m−1)−2m x^(m−1)+m²x=0과 동치다. h는 0 오른쪽에서 음수이고 h(1)=(m−1)²>0이므로 양의 근이 있다. m≥2에서는 (2/m)x^(m−2)=1+x^(2m−2)/m²에서 좌변≤1<우변이므로 양의 근이 없다. 따라서 0<m<1 또는 m≥2이다.\n두 주사위는 독립이다. 한 번의 합산 변위 −4,−1,1,2,4의 확률은 차례로 1/6,5/12,1/6,1/6,1/12이다. 한 번의 기댓값은 −1/4이고 선형성으로 세 번 합은 −3/4이다.","logical_id":"c40a215a-ebb1-56e2-bade-5d2beec360e3","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('c40a215a-ebb1-56e2-bade-5d2beec360e3','144f5cd5-dca6-5b40-9b91-a4c2311d78df','e84e5e0e-677c-5ff3-9044-708d4ee08d8a','OFFICIAL','현의 중점 M은 OM=1/2이다. 사면체의 높이와 밑넓이를 비교하면 최대일 때 H는 AB의 수직이등분선 위에서 O를 기준으로 M 반대편에 있다. t=OH라 하면 부피는 √3(2t+1)√(1−t²)/12. 도함수 부호가 바뀌는 t=(√33−1)/8에서 밑넓이는 √3(1/2+t)/2=3(√3+√11)/16이다.
원점은 항상 교점이다. 0<m<1에서는 0<x≤1에서 g(x)≤x<f(x). m=1에서는 (1,1)도 교점이다. 1<m<2에서는 양의 교점 방정식이 h(x)=x^(2m−1)−2m x^(m−1)+m²x=0과 동치다. h는 0 오른쪽에서 음수이고 h(1)=(m−1)²>0이므로 양의 근이 있다. m≥2에서는 (2/m)x^(m−2)=1+x^(2m−2)/m²에서 좌변≤1<우변이므로 양의 근이 없다. 따라서 0<m<1 또는 m≥2이다.
두 주사위는 독립이다. 한 번의 합산 변위 −4,−1,1,2,4의 확률은 차례로 1/6,5/12,1/6,1/6,1/12이다. 한 번의 기댓값은 −1/4이고 선형성으로 세 번 합은 −3/4이다.','c40a215a-ebb1-56e2-bade-5d2beec360e3',1,'DRAFT'); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solution_steps t where id='84e68d08-1a14-558d-9ee4-3ea253f8ca82'; if prior is not null then if not prior @> '{"id":"84e68d08-1a14-558d-9ee4-3ea253f8ca82","solution_id":"c40a215a-ebb1-56e2-bade-5d2beec360e3","position":1,"body":"현의 중점 M은 OM=1/2이다. 사면체의 높이와 밑넓이를 비교하면 최대일 때 H는 AB의 수직이등분선 위에서 O를 기준으로 M 반대편에 있다. t=OH라 하면 부피는 √3(2t+1)√(1−t²)/12. 도함수 부호가 바뀌는 t=(√33−1)/8에서 밑넓이는 √3(1/2+t)/2=3(√3+√11)/16이다.","criterion_id":null}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solution_steps (id,solution_id,position,body,criterion_id) values ('84e68d08-1a14-558d-9ee4-3ea253f8ca82','c40a215a-ebb1-56e2-bade-5d2beec360e3',1,'현의 중점 M은 OM=1/2이다. 사면체의 높이와 밑넓이를 비교하면 최대일 때 H는 AB의 수직이등분선 위에서 O를 기준으로 M 반대편에 있다. t=OH라 하면 부피는 √3(2t+1)√(1−t²)/12. 도함수 부호가 바뀌는 t=(√33−1)/8에서 밑넓이는 √3(1/2+t)/2=3(√3+√11)/16이다.',NULL); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solution_steps t where id='5b4df75b-3683-5aa0-96fe-5a49e4da9c78'; if prior is not null then if not prior @> '{"id":"5b4df75b-3683-5aa0-96fe-5a49e4da9c78","solution_id":"c40a215a-ebb1-56e2-bade-5d2beec360e3","position":2,"body":"원점은 항상 교점이다. 0<m<1에서는 0<x≤1에서 g(x)≤x<f(x). m=1에서는 (1,1)도 교점이다. 1<m<2에서는 양의 교점 방정식이 h(x)=x^(2m−1)−2m x^(m−1)+m²x=0과 동치다. h는 0 오른쪽에서 음수이고 h(1)=(m−1)²>0이므로 양의 근이 있다. m≥2에서는 (2/m)x^(m−2)=1+x^(2m−2)/m²에서 좌변≤1<우변이므로 양의 근이 없다. 따라서 0<m<1 또는 m≥2이다.","criterion_id":null}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solution_steps (id,solution_id,position,body,criterion_id) values ('5b4df75b-3683-5aa0-96fe-5a49e4da9c78','c40a215a-ebb1-56e2-bade-5d2beec360e3',2,'원점은 항상 교점이다. 0<m<1에서는 0<x≤1에서 g(x)≤x<f(x). m=1에서는 (1,1)도 교점이다. 1<m<2에서는 양의 교점 방정식이 h(x)=x^(2m−1)−2m x^(m−1)+m²x=0과 동치다. h는 0 오른쪽에서 음수이고 h(1)=(m−1)²>0이므로 양의 근이 있다. m≥2에서는 (2/m)x^(m−2)=1+x^(2m−2)/m²에서 좌변≤1<우변이므로 양의 근이 없다. 따라서 0<m<1 또는 m≥2이다.',NULL); end if; end $row$;
